function analyzePuzzle(p) {
 const n=p.regions.length;
 const cells=Array.from({length:n*n},(_,i)=>({r:Math.floor(i/n),c:i%n,z:p.regions[Math.floor(i/n)][i%n]}));
 let candidates=new Set(cells.map((_,i)=>i)), placed=[], singles=0, locked=0;
 const groups=[];
 for(const type of ['r','c','z'])for(let k=0;k<n;k++)groups.push({type,k,ids:cells.flatMap((x,i)=>x[type]===k?[i]:[])});
 function place(id){const x=cells[id];placed.push(id);for(const i of candidates){const y=cells[i];if(x.r===y.r||x.c===y.c||x.z===y.z||(Math.abs(x.r-y.r)<=1&&Math.abs(x.c-y.c)<=1))candidates.delete(i);}}
 while(placed.length<n){
  let changed=false;
  for(const g of groups){if(placed.some(i=>cells[i][g.type]===g.k))continue;const ids=g.ids.filter(i=>candidates.has(i));if(ids.length===1){place(ids[0]);singles++;changed=true;break;}}
  if(changed)continue;
  for(const g of groups){if(placed.some(i=>cells[i][g.type]===g.k))continue;const ids=g.ids.filter(i=>candidates.has(i));if(!ids.length)continue;
   for(const type of ['r','c','z']){if(type===g.type)continue;const values=new Set(ids.map(i=>cells[i][type]));if(values.size!==1)continue;const k=[...values][0];for(const i of [...candidates])if(cells[i][type]===k&&!g.ids.includes(i)){candidates.delete(i);changed=true;}}
  }
  if(changed){locked++;continue;}break;
 }
 return {difficulty:placed.length<n?'hard':locked?'medium':'easy',singles,locked,resolved:placed.length,size:n};
}

